const b = $input.first().json.body || $input.first().json;

const empId = Number(b.employee_id);
if (!empId) throw new Error('Не указан employee_id');

const scores = Array.isArray(b.scores) ? b.scores : [];
const clean = [];
for (const s of scores) {
  const lvl = Number(s.ku_level);
  if (!s.competency_name) continue;
  if (lvl < 1 || lvl > 5) continue;
  clean.push({ competency_name: String(s.competency_name), ku_level: lvl });
}

return [{ json: {
  employee_id: empId,
  company:     String(b.company || '').replace(/'/g, "''"),
  held_at:     String(b.held_at || '').slice(0, 10),
  comment:     String(b.comment || '').replace(/'/g, "''"),
  imported_by: Number(b.imported_by) || null,
  scores_json: JSON.stringify(clean).replace(/'/g, "''"),
  count:       clean.length
}}];
